<?php
namespace App\Modules\Sales\Domain\Models;
use App\Models\User;use App\Modules\Finance\Domain\Enums\FinancialDocumentStatus;use App\Modules\Finance\Domain\Models\JournalEntry;use App\Modules\Inventory\Domain\Models\InventoryMovement;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['document_number','sale_id','returned_at','status','total_refund','total_cost','reason','created_by','inventory_movement_id','journal_entry_id'])]
class SaleReturn extends Model {use HasUlids;public function sale():BelongsTo{return $this->belongsTo(Sale::class);}public function lines():HasMany{return $this->hasMany(SaleReturnLine::class);}public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');}public function inventoryMovement():BelongsTo{return $this->belongsTo(InventoryMovement::class);}public function journalEntry():BelongsTo{return $this->belongsTo(JournalEntry::class);}protected function casts():array{return ['returned_at'=>'datetime','status'=>FinancialDocumentStatus::class,'total_refund'=>'integer','total_cost'=>'integer'];}}
